// Um disparo = um bulkId (mensagem avulsa: o próprio messageId). Custo REAL vem da Infobip (pricePerMessage).
// LGPD: não importa destinatário nem texto (SMS personalizado traria nome). Só lote, remetente, contagens e custo.
// Lote iniciado há mais de 46 h não é reenviado: parte dele já saiu da janela de 48 h e a contagem cairia.
const corte = Date.now() - 46 * 3600 * 1000;
const grupos = {};
for (const it of $input.all()) {
  for (const m of (it.json.results || [])) {
    const k = m.bulkId || m.messageId; if (!k) continue;
    const g = grupos[k] = grupos[k] || { k, ini: null, n: 0, ent: 0, fal: 0, custo: 0, moeda: null, sender: m.sender || m.from || '', ref: m.campaignReferenceId || null };
    const t = m.sentAt || m.doneAt; if (t && (!g.ini || t < g.ini)) g.ini = t;
    const qtd = Number(m.messageCount || 1);
    g.n += 1;
    const st = (m.status && m.status.groupName) || '';
    if (st === 'DELIVERED') g.ent += 1;
    if (['UNDELIVERABLE', 'REJECTED', 'EXPIRED'].includes(st)) g.fal += 1;
    if (m.price && m.price.pricePerMessage != null) { g.custo += Number(m.price.pricePerMessage) * qtd; g.moeda = m.price.currency || g.moeda; }
  }
}
const lote = [];
for (const g of Object.values(grupos)) {
  if (!g.ini || Date.parse(g.ini.replace(/([+-]\d{2})(\d{2})$/, '$1:$2')) < corte) continue;
  const item = {
    id_externo: String(g.k),
    campanha: g.ref,
    enviado_em: g.ini.replace(/([+-]\d{2})(\d{2})$/, '$1:$2'),
    canal: 'sms',
    copy_texto: `SMS enviado pela Infobip${g.sender ? ' (remetente ' + g.sender + ')' : ''}. Texto não importado.`,
    copy_link: 'https://portal.infobip.com/analyze/logs',
    publico_lista: `Infobip — lote ${String(g.k).slice(0, 60)}`,
    tamanho_lista: g.n,
    entregues: g.ent,
    falhas: g.fal,
  };
  if (g.moeda === 'BRL') item.custo_centavos = Math.round(g.custo * 100);
  lote.push(item);
}
return [{ json: { total: lote.length, lote: lote.slice(0, 1000) } }];
